(* [comment removed for export] *)
Lemma mb_out_range `{HeapCeil} : forall b es insz, mb_addr_ok b es -> 0 < b -> b + 64 <= aceil -> 0 <= mb_out b es insz < 2^64.
Proof.
  intros b es insz AOK B0 BH. pose proof aceil_facts as (AF1 & _ & _). unfold mb_out.
  destruct (mb_full es insz); [clear - AF1 B0 BH; lia|].
  destruct es as [|e es']; [cbn; clear - AF1 B0 BH; lia|].
  destruct (mb_es_snoc_inv (e :: es') ltac:(discriminate)) as (P & xl & sl & EP). rewrite EP, mb_lasta_snoc.
  destruct (mb_addr_ok_elem _ _ xl sl AOK ltac:(rewrite EP; apply in_app_iff; right; left; reflexivity)) as (X0 & _ & S0 & S24 & _ & _ & _ & XH & _).
  unfold AAPP_HI in XH. clear - X0 S0 S24 XH. lia.
Qed.

