Lemma aobj_cw : forall s LB m0 LF m1 O n l h,
  as_RHEAP H s LB m0 -> as_RFS H LF m1 -> aobj LB LF O n -> O <= l -> l <= h -> h <= O + n -> aclient_write_ok H LB (l, h).
Proof.
  intros s LB m0 LF m1 O n l h RH RF AO K1 K2 K3. replace (l, h) with (l, l + (h - l)) by (f_equal; lia).
  exact (proj1 (aobj_write_ok H HH _ _ _ _ _ _ _ RH RF (aobj_sub LB LF O n l (h - l) AO K1 ltac:(lia)))).
Qed.

Definition prep_WN (lo : Z) (sp : word) (ff fp b res : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + 128); (sh ff, sh ff + 16); (b + 24, b + 64); (res, res + 40)]%Z.

Definition prep_segN_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LF : list fframe) (lo shi res b : Z) (es : list mbe) (insz n : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (ff fp : Z),
