Scheme kc__5 := Elimination for Corelib.Init.Logic.False Sort Prop.

Lemma prep_seg2 : forall (sp gp tp : word) (s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra : word) (F : bvmap 5 word) (fc : bv 32)
    (pcv t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word)
    (m : mem) (LF : list fframe) (LB : list block) (s2_ : as_St H) (p : bptr)
    (lo shi spa ff fp res b : Z) (es : list mbe) (insz n x g oe : Z) (gap : list cell) (j0 j24 j96 j120 h32 h112 rj j16 jx : list byte),
  (pcv = Z_to_bv 64 P_A_PREP_ALLOCRET \/ pcv = ret_pc (Z_to_bv 64 P_A_PREP_ALLOCRET)) ->
  mb_need es insz n = true -> g = mb_grow es insz n -> mb_ok es insz -> 1 <= n -> insz + n <= 2^26 ->
  (spa = bv_unsigned sp + -288 \/ spa = bv_unsigned sp + -304) -> spa mod 32 = 0 ->
  lo + 304 + MB_SR_STACK <= bv_unsigned sp -> aceil <= lo -> bv_unsigned sp <= shi -> bv_unsigned ra mod 2 = 0 ->
  fresh_frame H LF 1 ff fp -> as_RFS H ((1, ff, fp) :: LF) m -> ACONST m -> stack0 m lo shi -> stk bsegs m lo spa -> mem_inv bsegs m ->
  rw_cells bsegs m spa (prep_locals1 b n ff j0 j24 j96 j120) ->
  rw_cells bsegs m (spa + 184) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -104 - (spa + 184) ->
  rw_cells bsegs m (bv_unsigned sp + -104) (prep_saves s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
  rw_cells bsegs m ff (prep_ff1 ff spa fp h32 h112) ->
  rw_cells bsegs m (Z.shiftr ff 3 + 2147450880) prep_sh1 ->
  rw_cells bsegs m fp [C1 (b8 1)] ->
  rw_cells bsegs m res [CB 40 rj] -> accessible m res 40 -> res mod 8 = 0 -> mb_off b es res 40 ->
  AMBraw m b es (mb_out b es insz) insz (mb_outpos es insz) oe ->
  rw_cells bsegs m x [CB 16 j16] -> rw_cells bsegs m (x + 16) [C8 (Z_to_bv 64 g); CB (Z.to_nat (mb_block_size g - 24)) jx] ->
  addressable m x (mb_block_size g) -> rblock_range x (mb_block_size g) ->
  (x + mb_block_size g <= b \/ b + 64 <= x) -> (res + 40 <= x \/ x + mb_block_size g <= res) ->
  (forall x' s', In (x', s') es -> x + mb_block_size g <= x' \/ x' + mb_block_size s' <= x) ->
  as_RHEAP H s2_ ((p, x, mb_block_size g) :: LB) m -> aobj LB LF b 64 -> aobj LB LF res 40 -> AMBufOwn LB es ->
  (b + 64 <= ff \/ ff + 128 <= b) -> (b + 64 <= fp \/ fp + 1 <= b) -> (res + 40 <= ff \/ ff + 128 <= res) -> (res + 40 <= fp \/ fp + 1 <= res) ->
  evt bsegs (prep_seg2_post sp gp tp s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra F fc LF lo shi spa ff fp res b es insz n x m)
    (MS (mkR (Z_to_bv 64 P_A_PREP_ALLOCRET) (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa) (Z_to_bv 64 x) a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 (insz + n - mb_cap es)) (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 res) (Z_to_bv 64 b)
             (Z_to_bv 64 2147450880) (Z_to_bv 64 ff) (Z_to_bv 64 (b + 8)) (Z_to_bv 64 ff) (Z_to_bv 64 (ff + 96)) (Z_to_bv 64 (b + 56))
             t3 t4 t5 t6)
        F pcv fc None m (seg_rom bsegs)).
